{"HelperA.dfy": "A.ObserveMove(m, a, b);
    var m1 := K.Move(m, a, b);
    assert m1.Keys == (m.Keys - {a}) + {b};
    assert b in m1;
    assert c !in m1;
    assert b != c;
    A.ObserveMove(m1, b, c);
    var m2 := K.Move(m1, b, c);
    assert m2.Keys == (m1.Keys - {b}) + {c};
    A.ObserveMove(m, a, c);
    var m3 := K.Move(m, a, c);
    assert m3.Keys == (m.Keys - {a}) + {c};
    assert m2.Keys == m3.Keys;
    assert forall q :: q in m2 ==> q in m3 && m2[q] == m3[q];
    A.Equal(m2, m3);", "HelperB.dfy": "A.ObserveMove(m, a, b);
    var m1 := K.Move(m, a, b);
    assert m1.Keys == (m.Keys - {a}) + {b};
    assert b in m1;
    assert c !in m1;
    assert b != c;
    A.ObserveMove(m1, b, c);
    var m2 := K.Move(m1, b, c);
    assert m2.Keys == (m1.Keys - {b}) + {c};
    A.ObserveMove(m, a, c);
    var m3 := K.Move(m, a, c);
    assert m3.Keys == (m.Keys - {a}) + {c};
    assert m2.Keys == m3.Keys;
    assert forall q :: q in m2 ==> q in m3 && m2[q] == m3[q];
    A.Equal(m2, m3);"}

